    ('5137c62f-7a51-4144-9ee1-9bd565b10bc8'::uuid, 'card_description', 'Rivas District, a Chiriqui Period site of AD 750-1500, gave up residential areas of river cobbles laid in circles 10 to 30 metres across. Paths, plazas and stairways were recorded here.', NULL, 'teaser-card-s033-rollback:5137c62f-7a51-4144-9ee1-9bd565b10bc8:card_description', 'rollback of teaser-card-s033: card_description None restored on Rivas District', '2b5a8d7bbbd4e3362fbee7565f6a1f8eac0219b43f3f45a503586a68c9a80e22|828c698d8982c145453ffc2aafca457c5704b026e447d917783a507ef87fc0c0|828c698d8982c145453ffc2aafca457c5704b026e447d917783a507ef87fc0c0', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-007", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Rivas District, a Chiriqui Period site of AD 750-1500, gave up residential areas of river cobbles laid in circles 10 to 30 metres across. Paths, plazas and stairways were recorded here."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Rivas District is a Chiriqui Period site of AD 750-1500 [S1]; researchers identified residential areas with river cobble structures laid in circular patterns [S3]; the circular patterns range from 10 to 30 metres in diameter [S3]; paths, plazas and stairways were recorded at the site [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Rivas is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Rivas_District]; Rivas lies in Costa Rica [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Rivas_District]; The site belongs to the Chiriqui Period, dated AD 750-1500 [SUPPORTED: https://en.wikipedia.org/wiki/Rivas_District]; Excavations identified several residential areas [SUPPOR