    ('5144ec8c-3071-4484-83d5-aded69094bb0'::uuid, 'card_description', 'In Luhansk Oblast, Ukraine, the Merheleva Ridge is an Eneolithic temple and burial complex of four large stone kurgans, officially announced on September 7, 2006.', NULL, 'teaser-card-s033-rollback:5144ec8c-3071-4484-83d5-aded69094bb0:card_description', 'rollback of teaser-card-s033: card_description None restored on Merheleva Ridge', 'd7c9f2c08615c2508ab49713b03d60ef2bceabd12a4c163cbe3ff92110a5eaa3|438ce4cc758d9f99d40d87a85586930642ae43e8749cabfefb275053298ddcb9|438ce4cc758d9f99d40d87a85586930642ae43e8749cabfefb275053298ddcb9', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "In Luhansk Oblast, Ukraine, the Merheleva Ridge is an Eneolithic temple and burial complex of four large stone kurgans, officially announced on September 7, 2006."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "it is in Luhansk Oblast, Ukraine [S1]; it is an Eneolithic temple and burial complex [S1]; it features four large stone kurgans [S1]; it was officially announced on September 7, 2006 [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Merheleva Ridge is an Eneolithic temple and burial complex. [SUPPORTED: https://en.wikipedia.org/wiki/Merheleva_Ridge]; Merheleva Ridge consists of four large stone kurgans. [SUPPORTED: https://en.wikipedia.org/wiki/Merheleva_Ridge]; Merheleva Ridge is in Luhansk Oblast, Ukraine. [SUPPORTED: https://en.wikipedia.org/wiki/Merheleva_Ridge]; Merheleva Ridge was officially announced on 7 September 2006. [SUPPORTED: https://en.wikipedia.org/wiki/Merheleva_Ridge]"}]'::jsonb),
    ('52827c54-91cb-4902-99fb-7b0860a71e36'::uuid, 'card_description', NULL, '"Over the earth" in Nahuatl—a crossroads linking the Aztec capital to points south. The name refers to the ancient roads that converged here.', 'teaser-card-s033-rollback:52827c54-91cb-4902-99fb-7b0860a71e36:card_description', 'rollback of teaser-card-s033: card_description ''"Over the earth" in Nahuatl—a crossroads linking the Aztec capital to points south. The name refers to the ancient roads that converged here.'' restored on Tlalpan', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
    ('54a9488b-698d-4c49-94a4-c50dd43847fe'::uuid, 'card_description', 'Colha, one of the earliest Maya settlements, was occupied from 3400-1900 BC in the Early Preceramic period through the Middle Postclassic. Its trade may have reached the Greater Antilles.', NULL, 'teaser-card-s033-rollback:54a9488b-698d-4c49-94a4-c50dd43847fe:card_description', 'rollback of teaser-card-s033: card_description None restored on Colha', 'dd384c3da67e10bb590a93df68d0875d99151727fff48a1ef4960195f621c690|980a501283c1b77441900488178ab77269cd7fdfca09fa753c942a3951be224e|980a501283c1b77441900488178ab77269cd7fdfca09fa753c942a3951be224e', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-007", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Colha, one of the earliest Maya settlements, was occupied from 3400-1900 BC in the Early Preceramic period through the Middle Postclassic. Its trade may have reached the Greater Antilles."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Colha is one of the earliest Maya settlements [S2]; it was occupied from the Early Preceramic period (3400-1900 BC) through the Middle Postclassic period [S2]; Colha''s trade networks may have extended to the Greater Antilles [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Colha is a Maya archaeological site (settlement) in northern Belize [SUPPORTED: https://en.wikipedia.org/wiki/Colha,_Belize]; Colha is one of the earliest sites in the Maya region [SUPPORTED: https://en.wikipedia.org/wiki/Colha,_Belize]; Colha was occupied from 3400-1900 BC [SUPPORTED: https://en.wikipedia.org/wiki/Colha,_Belize]; That earliest occupation belongs to the Early Preceramic period [SUPPORTED: https://en.wikipedia.org/wiki/Colha,_Belize]; Colha''s occupation continued through the Middle Postclassic period [SUPPORTED: https://en.wikipedia.org/wiki/Colha,_Belize]; Colha''s trade may have extended to the Greater Antilles (stated as a possibility) [SUPPORTED: https://en.wikipedia.org/wiki/Colha,_Belize]"}]'::jsonb),
