    ('57ded976-9874-4832-8716-2b54c1fee102'::uuid, 'card_description', 'Table des Marchand is a dolmen on the megalithic site of Locmariaquer in Morbihan, Brittany, standing with the grand broken menhir of Er Grah and the tumulus of Er Grah.', NULL, 'teaser-card-s033-rollback:57ded976-9874-4832-8716-2b54c1fee102:card_description', 'rollback of teaser-card-s033: card_description None restored on Table des Marchand', 'aa27d5e0989c86afcf3e03c4d617800bc13699ad9067fa06178f6eef62fda886|e9eb38d3ab80c2fd476ec4c269d0994c4fb8375c00d7b353ecfa0a55ce53e1aa|e9eb38d3ab80c2fd476ec4c269d0994c4fb8375c00d7b353ecfa0a55ce53e1aa', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-007", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Table des Marchand is a dolmen on the megalithic site of Locmariaquer in Morbihan, Brittany, standing with the grand broken menhir of Er Grah and the tumulus of Er Grah."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Table des Marchand is a dolmen on the megalithic site of Locmariaquer [S1]; it lies in the department of Morbihan, in Brittany [S1]; it forms part of the Locmariaquer complex together with the grand broken menhir of Er Grah and the tumulus of Er Grah [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Table des Marchand is a dolmen [SUPPORTED: https://en.wikipedia.org/wiki/Locmariaquer_megaliths]; It stands on the megalithic site of Locmariaquer [SUPPORTED: https://en.wikipedia.org/wiki/Locmariaquer_megaliths]; Locmariaquer is in Morbihan, Brittany, in north-western France [SUPPORTED: https://en.wikipedia.org/wiki/Locmariaquer]; The dolmen stands with the Grand (Broken) Menhir of Er Grah [SUPPORTED: https://en.wikipedia.or