    ('5d8a7c0e-3d54-497b-a9dc-5c9cbee82670'::uuid, 'card_description', 'South of the river Vuka and northwest of Vinkovci in eastern Croatia, Markušica gave up a Scordisci site of the Late La Tene culture, dug in rescue work of the 1970s and 1980s.', NULL, 'teaser-card-s033-rollback:5d8a7c0e-3d54-497b-a9dc-5c9cbee82670:card_description', 'rollback of teaser-card-s033: card_description None restored on Markušica', '7145f4f90e6d6e8f0d4269c881c9be9153637040c3d34533e2aa0493378f8bb1|0b3073cb213d8735abdaa1a33e118f9bf51fb2fa078326d82b3badc38359adad|0b3073cb213d8735abdaa1a33e118f9bf51fb2fa078326d82b3badc38359adad', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-008", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "South of the river Vuka and northwest of Vinkovci in eastern Croatia, Markušica gave up a Scordisci site of the Late La Tene culture, dug in rescue work of the 1970s and 1980s."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "it lies south of the river Vuka and northwest of Vinkovci in eastern Croatia [S1]; a Scordisci archaeological site dating to the Late La Tene culture lies there [S2]; the site was excavated during rescue excavations in the 1970s and 1980s [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Markušica is the site of a Scordisci archaeological site (a Scordisci settlement site) [SUPPORTED: https://en.wikipedia.org/wiki/Marku%C5%A1ica]; The Scordisci site at Markušica dates to the late La Tene (La Tène) culture [SUPPORTED: https://en.wikipedia.org/wiki/Marku%C5%A1ica]; The Scordisci site at Markušica was excavated as part of rescue excavations [SUPPORTED: https://en.wikipedia.org/wiki/Marku%C5%A1ica]; The rescue excavation of the site took place in the 1970s and 1980s [SUPPORTED: https://en.wikipedia.org/wiki/Marku%C5%A1ica]; Markušica is located south of the river Vuka [SUPPORTED: https://en.wikipedia.org/wiki/Marku%C5%A1ica]; Markušica is located northwest of the town of Vinkovci [SUPPORTED: https://en.wikipedia.org/wiki/Marku%C5%A1ica]; Markušica is in eastern Croatia [SUPPORTED: https://en.wikipedia.org/wiki/Marku%C5%A1ica]"}]'::jsonb),
    ('5db5e2c0-081a-4c69-a8c6-6105ac870e5f'::uuid, 'card_description', 'Excavations beneath the floor of the Church of the Holy Apostles Peter and Paul at Ras uncovered black-figure pottery from the 7th-6th centuries BC and a 5th-century BC princely grave.', NULL, 'teaser-card-s033-rollback:5db5e2c0-081a-4c69-a8c6-6105ac870e5f:card_description', 'rollback of teaser-card-s033: card_description None restored on Church of the Holy Apostles Peter and Paul, Ras', 'c012ad3fddbe5f831591751b4308dc899ad6d6ab3d4a0fc82ba4f410c5654e04|1b165651d68c378098cbbbcb1871046b8a38f284d600c21335a20c824b3c13cd|1b165651d68c378098cbbbcb1871046b8a38f284d600c21335a20c824b3c13cd', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-008", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Excavations beneath the floor of the Church of the Holy Apostles Peter and Paul at Ras uncovered black-figure pottery from the 7th-6th centuries BC and a 5th-century BC princely grave."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the church is the Church of the Holy Apostles Peter and Paul at Ras [S1]; excavations beneath its floor unearthed black-figure pottery from the 7th-6th centuries BC [S2]; the same excavations unearthed a 5th-century BC princely grave [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The site is a church, the Church of the Holy Apostles Peter and Paul at Ras, Serbia (a Serbian Orthodox church on a hill of Ras) [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_the_Holy_Apostles_Peter_and_Paul,_Ras]; The church is dedicated to Saints Peter and Paul [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_the_Holy_Apostles_Peter_and_Paul,_Ras]; Excavations on the site unearthed black-figure pottery [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_the_Holy_Apostles_Peter_and_Paul,_Ras]; The black-figure pottery dates to the 7th and 6th centuries BC [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_the_Holy_Apostles_Peter_and_Paul,_Ras]; A 5th-century BC princely grave was uncovered [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_the_Holy_Apostles_Peter_and_Paul,_Ras]; The finds lay underneath/beneath the floor of the church [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_the_Holy_Apostles_Peter_and_Paul,_Ras]"}]'::jsonb),
    ('5ea99baa-5ab5-4f9f-adb9-48bc53e97363'::uuid, 'card_description', 'On the southeastern edge of the Abusir necropolis, the Lepsius No.25 Pyramid is a 5th Dynasty double tomb: the eastern tomb measures 27.7 by 21.5 m, and lacked a mortuary temple.', NULL, 'teaser-card-s033-rollback:5ea99baa-5ab5-4f9f-adb9-48bc53e97363:card_description', 'rollback of teaser-card-s033: card_description None restored on Lepsius No.25 Pyramid', '222d557bf2983265e4ff846392114125a3fe566c18e21f97840ae147421f832e|5e6063913c774534b6d777bc5b6e973465a6532647162e7fad6714f38f803ecb|5e6063913c774534b6d777bc5b6e973465a6532647162e7fad6714f38f803ecb', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-008", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "On the southeastern edge of the Abusir necropolis, the Lepsius No.25 Pyramid is a 5th Dynasty double tomb: the eastern tomb measures 27.7 by 21.5 m, and lacked a mortuary temple."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "it lies on the southeastern edge of the Abusir necropolis in Egypt [S1]; it is a 5th Dynasty double tomb [S1]; the eastern tomb measures 27.7 by 21.5 m [S2]; the complex lacked a mortuary temple [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Lepsius No. 25 (Lepsius XXV, the Double Pyramid) is a double monument / pair of adjacent tombs [SUPPORTED: https://en.wikipedia.org/wiki/Double_Pyramid]; It is located on the south-eastern edge of the Abusir necropolis [SUPPORTED: https://en.wikipedia.org/wiki/Double_Pyramid]; It was built during the 5th (Fifth) Dynasty [SUPPORTED: https://en.wikipedia.org/wiki/Double_Pyramid]; The eastern tomb (the larger of the two) has a base measurement of 27.7 m x 21.53 m (27.7 by 21.5 m) [SUPPORTED: https://en.wikipedia.org/wiki/Double_Pyramid]; The monument lacked a mortuary temple (there was no mortuary temple in the complex) [SUPPORTED: https://en.wikipedia.org/wiki/Double_Pyramid]"}]'::jsonb),
    ('5f0df994-58d2-4bd5-91be-252d6ae06f76'::uuid, 'card_description', 'Outside the walls of Pompeii, the Villa of Diomedes stands on two levels around 3500 square meters, facing what would have been the ancient coast line, though it is not clear it was his.', NULL, 'teaser-card-s033-rollback:5f0df994-58d2-4bd5-91be-252d6ae06f76:card_description', 'rollback of teaser-card-s033: card_description None restored on Villa of Diomedes', 'f8e8e7ee7c6170a36abef8f9bc824f301d5acc18cde833238bcdff4efe0c982a|ae923f6a2b8e7e6032c5c3296b52d95b848bce7de84da9f68280f8bf2b1cdbc4|ae923f6a2b8e7e6032c5c3296b52d95b848bce7de84da9f68280f8bf2b1cdbc4', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-008", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Outside the walls of Pompeii, the Villa of Diomedes stands on two levels around 3500 square meters, facing what would have been the ancient coast line, though it is not clear it was his."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "it lies outside the walls of Pompeii [S2, S5]; it is on two levels [S8]; it is around 3500 square meters [S6]; its garden side faces what would have been the ancient coast line [S7]; it is not clear that the villa was in fact Marcus Arrius Diomedes'' [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Villa of Diomedes is an ancient Roman villa near Pompeii, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Diomedes]; The villa is located outside the city walls of Pompeii, on its north side [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Diomedes]; The villa stands on two levels [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Diomedes]; The villa is around 3500 square meters [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Diomedes]; The villa (its garden side) faces what would have been the ancient coast line [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Diomedes]; It is not clear that the villa was in fact Diomedes''s (the attribution to Diomedes is uncertain) [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Diomedes]"}]'::jsonb),
    ('60ef45e0-fd0e-414c-a000-22ddccdd332b'::uuid, 'card_description', 'Roman occupation at Keal Cotes runs from the 1st to 4th century AD. A 1960s field walk uncovered tessellated mosaic floor tiles; ploughing has left only cropmarks, visible from the air.', NULL, 'teaser-card-s033-rollback:60ef45e0-fd0e-414c-a000-22ddccdd332b:card_description', 'rollback of teaser-card-s033: card_description None restored on Keal Cotes', '3518afcf530e4d228f13b5d305e4ba4177962d621da5b679731410652e52d17a|3b3527859ede025b297e4a08acd26335f7538d8ef4e3d927c0ba2e1963314a20|3b3527859ede025b297e4a08acd26335f7538d8ef4e3d927c0ba2e1963314a20', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-009", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Roman occupation at Keal Cotes runs from the 1st to 4th century AD. A 1960s field walk uncovered tessellated mosaic floor tiles; ploughing has left only cropmarks, visible from the air."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Roman occupation at Keal Cotes runs from the 1st to 4th century AD [S1]; A 1960s field walk uncovered tessellated mosaic floor tiles [S2]; ploughing has left only cropmarks [S3]; the cropmarks are visible from the air [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Keal Cotes is a place in Lincolnshire, England, where the remains of a substantial Roman villa or high status Romano-British farmhouse stand in a field at the south end of the village. [SUPPORTED: https://en.wikipedia.org/wiki/Keal_Cotes]; The Keal Cotes area was visited and occupied by the Romans from the 1st century until the 4th century AD. [SUPPORTED: https://en.wikipedia.org/wiki/Keal_Cotes]; An archaeological dig and field walk in the village took place during the 1960s, over a large field to the south of the village. [SUPPORTED: https://en.wikipedia.org/wiki/Keal_Cotes]; That 1960s dig and field walk discovered many tessellated mosaic floor tiles and roof tiles, indicating a substantial Roman villa or high status Romano-British farmhouse had stood on the site. [SUPPORTED: https://en.wikipedia.org/wiki/Keal_Cotes]; Several centuries of agricultural activity ploughed the site out, so only cropmark outlines of an extensive dwelling, visible on several aerial photographs, remain. [SUPPORTED: https://en.wikipedia.org/wiki/Keal_Cotes]"}]'::jsonb),
    ('62f21f04-c668-474e-8548-69bbdbc35620'::uuid, 'card_description', 'The Megarian Treasury at Olympia held the votive offerings of Megara: built mainly from limestone, with a roof of terracotta tiles, statues, limestone reliefs and carvings in cedarwood.', NULL, 'teaser-card-s033-rollback:62f21f04-c668-474e-8548-69bbdbc35620:card_description', 'rollback of teaser-card-s033: card_description None restored on Megarian Treasury, Olympia', 'e6a20eee07ade0771ffd70931235a5c655690f2c87c11fad339fb5652a3b6e5b|194f68f7bf3501c06edfa8e29cb4cf54296d7c5313b85993cb528e8857768dc8|194f68f7bf3501c06edfa8e29cb4cf54296d7c5313b85993cb528e8857768dc8', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Megarian Treasury at Olympia held the votive offerings of Megara: built mainly from limestone, with a roof of terracotta tiles, statues, limestone reliefs and carvings in cedarwood."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the Megarian Treasury at Olympia held the votive offerings of Megara [S1]; it was mainly built from limestone [S2]; its roof was made of terracotta tiles [S2]; it was adorned with statues [S3]; it was adorned with limestone reliefs [S3]; it was adorned with carvings in cedarwood [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Megarian Treasury is an ancient Greek building located in the sanctuary of Olympia. [SUPPORTED: https://en.wikipedia.org/wiki/Megarian_Treasury_(Olympia)]; The Megarian Treasury held votive offerings of the Greek city-state of Megara. [SUPPORTED: https://en.wikipedia.org/wiki/Megarian_Treasury_(Olympia)]; Pausanias records that the Megarians built a treasury and dedicated offerings in it. [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0160%3Abook%3D6%3Achapter%3D19%3Asection%3D12]; The offerings dedicated in the Megarian treasury included small cedar-wood figures inlaid with gold. [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0160%3Abook%3D6%3Achapter%3D19%3Asection%3D12]; The Megarian Treasury was mainly built from limestone. [SUPPORTED: https://en.wikipedia.org/wiki/Megarian_Treasury_(Olympia)]; The roof of the Megarian Treasury was made of terracotta tiles. [SUPPORTED: https://en.wikipedia.org/wiki/Megarian_Treasury_(Olympia)]; The building was adorned with several statues, including limestone reliefs and carvings in cedarwood. [SUPPORTED: https://en.wikipedia.org/wiki/Megarian_Treasury_(Olympia)]"}]'::jsonb),
    ('631de534-1de5-4dbc-ac03-ac5ee63eb84f'::uuid, 'card_description', 'Stobno was settled in prehistoric times: Bronze Age and Early Middle Age sites lie nearby, and the village is first written in 1259, in Piast-ruled Poland since the late 10th century.', NULL, 'teaser-card-s033-rollback:631de534-1de5-4dbc-ac03-ac5ee63eb84f:card_description', 'rollback of teaser-card-s033: card_description None restored on Stobno, Lower Silesian Voivodeship', '3ce76a8a799c5f3759b83c27847496d43c0839460dbfc5c44efeca4222e52c15|54ba788773b8ed46c323980473dd029b2f3c6b4d6db3e9ddb986ef8090898468|54ba788773b8ed46c323980473dd029b2f3c6b4d6db3e9ddb986ef8090898468', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-009", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Stobno was settled in prehistoric times: Bronze Age and Early Middle Age sites lie nearby, and the village is first written in 1259, in Piast-ruled Poland since the late 10th century."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Stobno was settled in prehistoric times [S1]; Bronze Age sites lie nearby [S2]; Early Middle Age sites lie nearby [S2]; the village is first written in 1259 [S3]; it was then part of Piast-ruled Poland [S3]; it had belonged to Piast-ruled Poland since the late 10th century [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Stobno is a village in Gmina Wolow, Wolow County, Lower Silesian Voivodeship, in south-western Poland. [SUPPORTED: https://en.wikipedia.org/wiki/Stobno,_Lower_Silesian_Voivodeship]; The settlement at Stobno dates back to prehistoric times. [SUPPORTED: https://en.wikipedia.org/wiki/Stobno,_Lower_Silesian_Voivodeship]; There are archaeological sites from the Bronze Age in Stobno. [SUPPORTED: https://en.wikipedia.org/wiki/Stobno,_Lower_Silesian_Voivodeship]; There are archaeological sites from the Early Middle Ages in Stobno. [SUPPORTED: https://en.wikipedia.org/wiki/Stobno,_Lower_Silesian_Voivodeship]; The earliest mention concerning this village dates from 1259. [SUPPORTED: https://en.wikipedia.org/wiki/Stobno,_Lower_Silesian_Voivodeship]; In 1259 Stobno was part of Piast-ruled Poland. [SUPPORTED: https://en.wikipedia.org/wiki/Stobno,_Lower_Silesian_Voivodeship]; Stobno was located within Piast-ruled Poland since the late 10th century. [SUPPORTED: https://en.wikipedia.org/wiki/Stobno,_Lower_Silesian_Voivodeship]"}]'::jsonb),
    ('63b855c8-c281-42d8-87ea-58aeeec070ef'::uuid, 'card_description', 'Mawk''allaqta, an archaeological settlement in southeastern Peru''s Puno Region, was declared a National Cultural Heritage by the country''s National Institute of Culture.', NULL, 'teaser-card-s033-rollback:63b855c8-c281-42d8-87ea-58aeeec070ef:card_description', 'rollback of teaser-card-s033: card_description None restored on Mawk''allaqta, Sandia', '18f4458592d5239e9d288c021ff357da2d01e3f3ba81e57118ae2b99196b9d5d|498feb4705a2cd7ca39bb12fd9a4e17d904500b3c85ed9db795b15cb59e5a050|498feb4705a2cd7ca39bb12fd9a4e17d904500b3c85ed9db795b15cb59e5a050', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-009", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Mawk''allaqta, an archaeological settlement in southeastern Peru''s Puno Region, was declared a National Cultural Heritage by the country''s National Institute of Culture."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Mawk''allaqta is an archaeological settlement [S1]; it is in the Puno Region of southeastern Peru [S1]; it was declared a National Cultural Heritage [S2]; the declaring body is the country''s National Institute of Culture [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Mawk''allaqta is an archaeological site in Peru. [SUPPORTED: https://en.wikipedia.org/wiki/Mawk%27allaqta,_Sandia]; Mawk''allaqta is located in the Puno Region, Sandia Province, Sandia District. [SUPPORTED: https://en.wikipedia.org/wiki/Mawk%27allaqta,_Sandia]; The Puno Region lies in the southeast of Peru. [SUPPORTED: https://en.wikipedia.org/wiki/Puno_Region]; The site was declared a National Cultural Heritage (Patrimonio Cultural) of Peru. [SUPPORTED: https://en.wikipedia.org/wiki/Mawk%27allaqta,_Sandia]; The National Cultural Heritage declaration was made by Peru''s National Institute of Culture. [SUPPORTED: https://en.wikipedia.org/wiki/Mawk%27allaqta,_Sandia]; Mawk''allaqta is an archaeological settlement (the card calls it a settlement; every source I opened calls it an archaeological site). [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('648faca1-d0ae-4830-83f6-54efdf0231fe'::uuid, 'card_description', 'Marpa''s ruins straddle both sides of the river in the Cotahuasi Canyon, around 3,400 metres deep. The Inca road may follow an older route built by the Wari culture, circa 500-900 AD.', NULL, 'teaser-card-s033-rollback:648faca1-d0ae-4830-83f6-54efdf0231fe:card_description', 'rollback of teaser-card-s033: card_description None restored on Marpa, Peru', '1fbf872b0389e86607c8df0f080212dd83123c0acb9d1d3d7b4f5bf7ab7cfb91|e69e22e3583284ebe8209f8ae02c23320aca1e923962b20315af2674d139164e|e69e22e3583284ebe8209f8ae02c23320aca1e923962b20315af2674d139164e', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-009", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Marpa''s ruins straddle both sides of the river in the Cotahuasi Canyon, around 3,400 metres deep. The Inca road may follow an older route built by the Wari culture, circa 500-900 AD."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Marpa is a ruin [S1]; the ruins straddle both sides of the river [S2]; they are in the Cotahuasi Canyon [S1]; the canyon is around 3,400 metres deep [S1]; the Inca road may follow an older route built by the Wari culture [S3]; the Wari culture dates from circa 500-900 AD [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Marpa is a ruined pre-Hispanic town located along the Cotahuasi Canyon in the Andes range of southern Peru. [SUPPORTED: https://en.wikipedia.org/wiki/Marpa,_Peru]; Marpa''s ruins straddle both sides of the river in the Cotahuasi Canyon. [UNVERIFIABLE, no proving quote: None]; The Cotahuasi Canyon is around 3,400 metres deep (the source gives approximately 3,354 metres). [SUPPORTED: https://en.wikipedia.org/wiki/Cotahuasi_Canyon]; The Inca road may have been built along the route of an older road. [SUPPORTED: https://en.wikipedia.org/wiki/Marpa,_Peru]; That older road was built by the Wari culture. [SUPPORTED: https://en.wikipedia.org/wiki/Marpa,_Peru]; The Wari culture was a dominant force in the highlands of central and southern Peru between 500 AD and 900 AD. [SUPPORTED: https://en.wikipedia.org/wiki/Marpa,_Peru]"}]'::jsonb),
    ('64c9b400-5cab-45f2-8662-03c24c4367ce'::uuid, 'card_description', 'The Pyramid of Amenemhat I at el-Lisht, built by the founder of the Twelfth Dynasty who moved the capital from Thebes to Itj-tawy, now stands at approximately 20 m.', NULL, 'teaser-card-s033-rollback:64c9b400-5cab-45f2-8662-03c24c4367ce:card_description', 'rollback of teaser-card-s033: card_description None restored on Pyramid of Amenemhat I', 'f896cab134d8b3757c9ca850de4557b526c81a96bd3926c2f5288f614d015f0e|2a6b1c37983ae5895c0ecddf9dd591119f70456c16512b139d05d0741880c38c|2a6b1c37983ae5895c0ecddf9dd591119f70456c16512b139d05d0741880c38c', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-009", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Pyramid of Amenemhat I at el-Lisht, built by the founder of the Twelfth Dynasty who moved the capital from Thebes to Itj-tawy, now stands at approximately 20 m."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the pyramid is at el-Lisht [S1]; it was built by the founder of the Twelfth Dynasty [S1]; that founder moved the capital from Thebes to Itj-tawy [S1]; the pyramid now stands at approximately 20 m [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-026 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The site is a pyramid, an Egyptian burial structure built at el-Lisht (Lisht) [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Amenemhat_I]; It was built by Amenemhat I [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Amenemhat_I]; Amenemhat I was the founder of the Twelfth Dynasty of Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Amenemhat_I]; He moved the royal capital to the new city named Amenemhat-itj-tawy (Itjtawy) [SUPPORTED: https://en.wikipedia.org/wiki/Twelfth_Dynast