    ('6e6a831d-bdce-400c-86af-9238e6af3e89'::uuid, 'card_description', NULL, 'A valley with an estimated 1,500 burial mounds spanning two millennia of Thracian civilization. Each new dig reveals painted tombs, gold treasure, or bronze armor.', 'teaser-card-s033-rollback:6e6a831d-bdce-400c-86af-9238e6af3e89:card_description', 'rollback of teaser-card-s033: card_description ''A valley with an estimated 1,500 burial mounds spanning two millennia of Thracian civilization. Each new dig reveals painted tombs, gold treasure, or bronze armor.'' restored on Valley of the Thracian Rulers', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
