    ('70037a24-6487-4834-9b50-5242289009fe'::uuid, 'card_description', 'The Roman Bath in York was uncovered in 1929–31 while the present building rose over an earlier inn. Its Roman bathing complex is still visible inside, a rare glimpse of Roman-era York.', NULL, 'teaser-card-s033-rollback:70037a24-6487-4834-9b50-5242289009fe:card_description', 'rollback of teaser-card-s033: card_description None restored on Roman Bath, York', '06aa78609de599da8d21676b080f9c541a676cb8cb821e573635ffb27827449b|3b9a84ccfe650b6bc6150b61c9d016872b4bd460fadfd9ffb6fa777543ca17aa|3b9a84ccfe650b6bc6150b61c9d016872b4bd460fadfd9ffb6fa777543ca17aa', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-010", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Roman Bath in York was uncovered in 1929–31 while the present building rose over an earlier inn. Its Roman bathing complex is still visible inside, a rare glimpse of Roman-era York."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the Roman Bath is in York [S1, S3]; the remains were uncovered in 1929-31 [S1]; the uncovering happened during the construction of the present building [S1]; the present building replaced an earlier inn [S1]; the Roman bathing complex is still visible inside the building [S3]; it offers a rare glimpse of Roman-era York [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-028 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Roman Bath stands in the city of York, England [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bath,_York]; The site is an ancient Roman bath house beneath the present building [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bath,_York]; The Roman remains were uncovered in 1929-31 [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bath,_York]; The present building replaced an earlier inn [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bath,_York]; The Roman remains of the bath can still be viewed inside the building [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bath,_York]; The caldarium and some other features of the baths are the visible parts [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bath,_York]; The site is a rare glimpse of Roman-era York [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('7008f483-697f-4f0b-b2c4-5b234d28d4c7'::uuid, 'card_description', 'Lakhmir Mound rises in the Naig Valley of Sindh as a conical hill above a lower section resembling a town, where black-on-red pottery of the Indus Valley civilization lies scattered.', NULL, 'teaser-card-s033-rollback:7008f483-697f-4f0b-b2c4-5b234d28d4c7:card_description', 'rollback of teaser-card-s033: card_description None restored on Lakhmir Mound', 'afb050b80fd31bc6e2c2003870de720960a01b2d35fa5a4564481757f62a6e6c|774918b8ed99509c71f505153cf1f05268165530839519ca620f3b13a74281dc|774918b8ed99509c71f505153cf1f05268165530839519ca620f3b13a74281dc', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-010", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Lakhmir Mound rises in the Naig Valley of Sindh as a conical hill above a lower section resembling a town, where black-on-red pottery of the Indus Valley civilization lies scattered."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Lakhmir Mound lies in the Naig Valley of Sindh [S1]; one of its two parts is a conical hill [S2]; the conical hill stands above a lower section resembling a town [S2]; black-on-red pottery characteristic of the Indus Valley civilization lies scattered there [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-028 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Lakhmir Mound is an archaeological site (a mound/tell of settlement, not a fort or tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Lakhmir_Mound]; Lakhmir Mound is located in the Naig Valley [SUPPORTED: https://en.wikipedia.org/wiki/Lakhmir_Mound]; Lakhmir Mound is in Sindh, Pakistan [SUPPORTED: https://en.wikipedia.org/wiki/Lakhmir_Mound]; The mound rises in a conical hill shape [SUPPORTED: https: