    ('70466849-1cf9-4af9-a442-7a4ffa6e24c9'::uuid, 'card_description', NULL, '3rd-century BC Hellenistic settlement with remains spanning to the 4th century AD. Stone ruins at Karaboluculu mark a hilltop community that persisted through six centuries of occupation.', 'teaser-card-s033-rollback:70466849-1cf9-4af9-a442-7a4ffa6e24c9:card_description', 'rollback of teaser-card-s033: card_description ''3rd-century BC Hellenistic settlement with remains spanning to the 4th century AD. Stone ruins at Karaboluculu mark a hilltop community that persisted through six centuries of occupation.'' restored on Karabölücülü Harabeleri', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
    ('723fc127-d8cb-4d46-b075-ce46593b5409'::uuid, 'card_description', 'On the Argolid coast, Asine is the city the Iliad of Homer gives to Diomedes of Argos. In 1922 Swedish Crown Prince Gustaf Adolf began excavations, Sweden''s first major fieldwork in Greece.', NULL, 'teaser-card-s033-rollback:723fc127-d8cb-4d46-b075-ce46593b5409:card_description', 'rollback of teaser-card-s033: card_description None restored on Asine', 'f0b14e01f499a6fced1949afc4139a7f7c2fc189c331703bfddbe4446b18cdb2|87ca7018ebc73087e01570ec38c112312e3de85d17bb004f141b2283dd3e3cfa|87ca7018ebc73087e01570ec38c112312e3de85d17bb004f141b2283dd3e3cfa', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-010", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "On the Argolid coast, Asine is the city the Iliad of Homer gives to Diomedes of Argos. In 1922 Swedish Crown Prince Gustaf Adolf began excavations, Sweden''s first major fieldwork in Greece."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Asine lies on the coast of the Argolid [S1]; Asine is a city [S1]; Homer''s Iliad mentions Asine as subject to Diomedes of Argos [S1]; in 1922 Swedish Crown Prince Gustaf Adolf began excavations [S3]; the excavations were Sweden''s first major fieldwork in Greece [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-028 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Asine stands on the Argolid coast, on an acropolis cliff jutting into the Argolis bay [SUPPORTED: https://www.sia.gr/en/articles.php?tid=338&page=1]; Asine is an ancient city of the Greek world [SUPPORTED: https://en.wikipedia.org/wiki/Asine]; Homer''s Iliad mentions Asine in the Catalogue of Ships [SUPPORTED: https://en.wikipedia.org/wiki/Asine]; In the Iliad Asine is given to Diomed