    ('8797faec-8590-4716-9763-310be93ef6ea'::uuid, 'card_description', 'Outside the city walls of Palmyra, in the Valley of the Tombs, stood the Tower of Elahbel. In its tombs were found fragments of very early Chinese silk yarns dated to the 1st century AD.', NULL, 'teaser-card-s033-rollback:8797faec-8590-4716-9763-310be93ef6ea:card_description', 'rollback of teaser-card-s033: card_description None restored on Tower of Elahbel', '3545fae6e9589266d65b1f37f46c5b03f6fbcfba69da7ec6ca53e3b7370e7070|b2f22feb90539ef295224d2e23d88bf09d4e758085e241696c4d7da5fbeb55b8|b2f22feb90539ef295224d2e23d88bf09d4e758085e241696c4d7da5fbeb55b8', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Outside the city walls of Palmyra, in the Valley of the Tombs, stood the Tower of Elahbel. In its tombs were found fragments of very early Chinese silk yarns dated to the 1st century AD."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the Tower of Elahbel stood outside the city walls of Palmyra [S2]; it stood in an area known as the Valley of the Tombs [S2]; fragments of very early Chinese silk yarns were found in the tombs at the tower [S3]; the silk yarns are dated to the 1st century AD [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Tower of Elahbel was a tower tomb near the ancient city of Palmyra in Syria [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_Elahbel]; It was a funerary building standing in a necropolis [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_Elahbel]; The tower stood outside the city walls of Palmyra [SUPPORTED: https://en.wikipedia.org/wiki/Tower_of_Elahbel]; The area outside th