    ('8ef67a96-2590-4382-b575-4a15f7c468fe'::uuid, 'card_description', 'Cova Foradà, a cave in a low hill near Oliva, gave up a maxilla and fragments of a cranium. In 2010 came the most complete Neanderthal skeleton ever found on the Iberian peninsula.', NULL, 'teaser-card-s033-rollback:8ef67a96-2590-4382-b575-4a15f7c468fe:card_description', 'rollback of teaser-card-s033: card_description None restored on Cova Foradà', 'dc51d4f4980a1dfd2f2416de2087f84efcc4f13b75efd44e6608c4e22410d355|e1a12dd3cd758995eae5450098b5ae2816cdf2c106c8b4a83a099fa42f329f40|e1a12dd3cd758995eae5450098b5ae2816cdf2c106c8b4a83a099fa42f329f40', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-011", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Cova Foradà, a cave in a low hill near Oliva, gave up a maxilla and fragments of a cranium. In 2010 came the most complete Neanderthal skeleton ever found on the Iberian peninsula."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Cova Forada is a cave [S1]; the cave lies in a low hill [S4]; the cave is near Oliva [S1]; a maxilla was found there [S6]; fragments of a cranium were found there [S6]; in 2010 the most complete Neanderthal skeleton ever found on the Iberian peninsula was found there [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The site is a cave [SUPPORTED: https://en.wikipedia.org/wiki/Cova_Forad%C3%A0]; The cave is near Oliva, in the Province of Valencia, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Cova_Forad%C3%A0]; The cave is found in a low hill [SUPPORTED: https://en.wikipedia.org/wiki/Cova_Forad%C3%A0]; A maxilla was found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Cova_Forad%C3%A0]; Fragments o