    ('a692e959-c6b4-45b5-96f6-65b82c883a35'::uuid, 'card_description', 'Taliata was a Roman fort on the Moesian Limes, the chain of forts along the Danube. Domitian gave its wood and earth walls stone faces in 87 AD; an early Christian basilica was found there.', NULL, 'teaser-card-s033-rollback:a692e959-c6b4-45b5-96f6-65b82c883a35:card_description', 'rollback of teaser-card-s033: card_description None restored on Taliata', '6836087e638b2d9622dc06620cc82d64df8b0bd85a7f0758bc12796d6c5e87d9|d6f1d857d95fd2264ccbd1722a5cdbf7a31c28b25cac94f3485743c2d16a9792|d6f1d857d95fd2264ccbd1722a5cdbf7a31c28b25cac94f3485743c2d16a9792', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-011", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Taliata was a Roman fort on the Moesian Limes, the chain of forts along the Danube. Domitian gave its wood and earth walls stone faces in 87 AD; an early Christian basilica was found there."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Taliata was a Roman fort [S1]; it was part of the Roman Moesian Limes frontier system of linked forts along the Danube [S3]; Domitian replaced its wood and earth walls by stone walls in 87 AD [S4]; an early Christian basilica was discovered on the site [S7]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Taliata is a Roman town and fort in eastern Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Taliata]; The fort was built as part of the Roman Moesian Limes [SUPPORTED: https://en.wikipedia.org/wiki/Taliata]; The Moesian Limes is a chain of linked forts along the Danube [SUPPORTED: https://en.wikipedia.org/wiki/Taliata]; Domitian replaced the fort''s wood and earth walls with stone in 87 AD [SUP