    ('b7cc5073-ffca-4cd3-a168-3062908d4959'::uuid, 'card_description', 'On top of a South Downs hill, the Beacon Hill fort is a single rampart and a flat-bottomed ditch, now a low bank up to 6 metres wide. The area also holds an Anglo-Saxon burial mound.', NULL, 'teaser-card-s033-rollback:b7cc5073-ffca-4cd3-a168-3062908d4959:card_description', 'rollback of teaser-card-s033: card_description None restored on Beacon Hill, West Sussex', 'cf62e1ac70ba896bf073a9091727b51d2e32551c9980817602db1d14968f8ac8|ca9aa13116848c72b888924d605b5c9d230a2484f59f6598b9ca57f2797bbaa8|ca9aa13116848c72b888924d605b5c9d230a2484f59f6598b9ca57f2797bbaa8', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-011", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "On top of a South Downs hill, the Beacon Hill fort is a single rampart and a flat-bottomed ditch, now a low bank up to 6 metres wide. The area also holds an Anglo-Saxon burial mound."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the hillfort stands on top of a hill on the South Downs [S1, S7]; the fort is defined by a single rampart and a flat-bottomed ditch [S7]; the ditch survives as a low bank up to 6 metres wide [S7]; the area of the fort also includes an Anglo-Saxon burial mound [S6]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Beacon Hill is a hillfort on the South Downs [SUPPORTED: https://en.wikipedia.org/wiki/Beacon_Hill,_West_Sussex]; The hillfort is situated on the top of the hill [SUPPORTED: https://en.wikipedia.org/wiki/Beacon_Hill,_West_Sussex]; The fort is defined by a single rampart [SUPPORTED: https://en.wikipedia.org/wiki/Beacon_Hill,_West_Sussex]; The fort is defined by a flat-bottomed ditch [SU