    ('b8f4c5f4-c567-4605-9f3d-9475d2db6362'::uuid, 'card_description', 'In Dulan Village, the Dulan Site holds a rectangular stony coffin, dug during Japanese rule, and a giant stone pile found by Academia Sinica. Its objects date back to 3,000 years ago.', NULL, 'teaser-card-s033-rollback:b8f4c5f4-c567-4605-9f3d-9475d2db6362:card_description', 'rollback of teaser-card-s033: card_description None restored on Dulan Site', '7dfd183b4d0bb876710cb2e695f70ced29c6e5acef6541efaa09acf0349b73a7|fddeeb9ee4134ed1517660440e5c97f4c77b6334de12b0a183cad4b84cc6f9a4|fddeeb9ee4134ed1517660440e5c97f4c77b6334de12b0a183cad4b84cc6f9a4', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-011", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "In Dulan Village, the Dulan Site holds a rectangular stony coffin, dug during Japanese rule, and a giant stone pile found by Academia Sinica. Its objects date back to 3,000 years ago."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the Dulan Site is in Dulan Village [S1]; a rectangular stony coffin was excavated in the area during Japanese rule of Taiwan [S2]; a giant stone pile was discovered by Academia Sinica [S3]; the site''s objects date back to 3,000 years ago [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Dulan Site is an archaeological site in Dulan Village, Donghe Township, Taitung County, Taiwan [SUPPORTED: https://en.wikipedia.org/wiki/Dulan_Site]; A rectangular stony coffin was excavated at the site [SUPPORTED: https://en.wikipedia.org/wiki/Dulan_Site]; That excavation took place during Japanese rule of Taiwan [SUPPORTED: https://en.wikipedia.org/wiki/Dulan_Site]; Further investigation led to the discovery of 