    ('c17927cb-4b63-4fa0-9c64-b72a65decaaa'::uuid, 'card_description', 'On Rhodes in the Dodecanese, the acropolis of Lindos was dominated by the massive temple of Athena Lindia, which attained its final form around 300 BC, and was excavated down to bedrock.', NULL, 'teaser-card-s033-rollback:c17927cb-4b63-4fa0-9c64-b72a65decaaa:card_description', 'rollback of teaser-card-s033: card_description None restored on Lindos', '96a71fff386a1b02caac5d7bbd45837012034907bfdded86286ab89ff3c06f65|7d41e378a59967ef66932f509a3d28258f5ffa26b5f446aaa9cbf3c0afe2a368|7d41e378a59967ef66932f509a3d28258f5ffa26b5f446aaa9cbf3c0afe2a368', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-011", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "On Rhodes in the Dodecanese, the acropolis of Lindos was dominated by the massive temple of Athena Lindia, which attained its final form around 300 BC, and was excavated down to bedrock."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Lindos is on Rhodes in the Dodecanese [S1, S4]; the acropolis of Lindos was dominated by the massive temple of Athena Lindia [S6]; the temple attained its final form around 300 BC [S6]; the acropolis site was excavated down to bedrock [S8]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The acropolis of Lindos was dominated by the massive temple of Athena Lindia [SUPPORTED: https://en.wikipedia.org/wiki/Lindos]; That temple, of Athena Lindia, attained its final form in around 300 BC [SUPPORTED: https://en.wikipedia.org/wiki/Lindos]; The acropolis of Lindos was excavated down to bedrock [SUPPORTED: https://en.wikipedia.org/wiki/Lindos]; Lindos lies on Rhodes (it forms part of the municipality of Rhodes) [SUPPORTED: https://en.wikipedia.org/wiki/Lindos]; Rhodes is one of the Dodecanese islands [SUPPORTED: https://en.wikipedia.org/wiki/Rhodes]"}]'::jsonb),
    ('c8529ed4-208b-45d2-9e75-58a5c3022c82'::uuid, 'card_description', 'The ruins of Pushkalavati are two sites, Bala Hisar to the south and Shaikhan Dheri to the north. According to Arrian, the city surrendered in 327/326 BCE to Alexander the Great.', NULL, 'teaser-card-s033-rollback:c8529ed4-208b-45d2-9e75-58a5c3022c82:card_description', 'rollback of teaser-card-s033: card_description None restored on Pushkalavati', '7060dc79fd3d28c1f8c0e7b2cffd3bec7198ed33ba2d414df51c3b242d7d180b|8bf9a7d0b91528211506fa1e838a7078a0829f07f96839565e459930fec39843|8bf9a7d0b91528211506fa1e838a7078a0829f07f96839565e459930fec39843', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-011", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The ruins of Pushkalavati are two sites, Bala Hisar to the south and Shaikhan Dheri to the north. According to Arrian, the city surrendered in 327/326 BCE to Alexander the Great."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the ruins of Pushkalavati consist of two sites [S4]; Bala Hisar is to the south [S5]; Shaikhan Dheri is to the north [S6]; according to Arrian the city surrendered in 327/326 BCE to Alexander the Great [S7]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The ruins of Pushkalavati consist of two sites, separated by the Shambor river [SUPPORTED: https://en.wikipedia.org/wiki/Pushkalavati]; Bala Hisar is the southern of the two sites [SUPPORTED: https://en.wikipedia.org/wiki/Pushkalavati]; Shaikhan Dheri is the northern of the two sites [SUPPORTED: https://en.wikipedia.org/wiki/Pushkalavati]; According to Arrian, the city then surrendered in 327/326 BCE to Alexander the Great, who established a garrison in it [SUPPORTED: https://en.wikipedia.org/wiki/Pushkalavati]; The city then surrendered in 327/326 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Pushkalavati]"}]'::jsonb),
    ('c8e0a91d-298d-40f1-aef8-f8503e44b05a'::uuid, 'card_description', 'Across the fens, the Fen Causeway runs 24 miles from Denver to Peterborough, thought raised on gravel up to 60 feet wide. Near its western end lies the Bronze Age route across Flag Fen.', NULL, 'teaser-card-s033-rollback:c8e0a91d-298d-40f1-aef8-f8503e44b05a:card_description', 'rollback of teaser-card-s033: card_description None restored on Fen Causeway', 'f01782f5e7b6a984496ef13f47a6a5534e72cdb4344e9c7334634fe98451a859|5f894d3b2c07759df8cf2321f2e110fa56337a61d7e3fafa707796b9d4ede79e|5f894d3b2c07759df8cf2321f2e110fa56337a61d7e3fafa707796b9d4ede79e', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-011", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Across the fens, the Fen Causeway runs 24 miles from Denver to Peterborough, thought raised on gravel up to 60 feet wide. Near its western end lies the Bronze Age route across Flag Fen."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the Fen Causeway runs across the fens [S4]; it runs 24 miles [S2]; it runs between Denver and Peterborough [S1]; the road is thought to have been raised above the marshy fens using gravel [S4]; the road is up to 60 feet wide [S4]; near its western end is the Bronze Age route across Flag Fen [S5]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Fen Causeway is a Roman road of England that runs from Denver, Norfolk in the east to Peterborough in the west [SUPPORTED: https://en.wikipedia.org/wiki/Fen_Causeway]; The Fen Causeway is a road across the fens that provided a link from the north and west of England to East Anglia [SUPPORTED: https://en.wikipedia.org/wiki/Fen_Causeway]; Denver acted as the terminus for the Fen Causeway, a Roman road [SUPPORTED: https://en.wikipedia.org/wiki/Denver,_Norfolk]; The Fen Causeway''s path covers 24 miles [SUPPORTED: https://en.wikipedia.org/wiki/Fen_Causeway]; The Fen Causeway was thought to have been raised above the marshy fens [SUPPORTED: https://en.wikipedia.org/wiki/Fen_Causeway]; The Fen Causeway was made using gravel [SUPPORTED: https://en.wikipedia.org/wiki/Fen_Causeway]; The Fen Causeway has a width of up to 60 feet [SUPPORTED: https://en.wikipedia.org/wiki/Fen_Causeway]; Towards its western end the Fen Causeway is close to the Bronze Age route across Flag Fen [SUPPORTED: https://en.wikipedia.org/wiki/Fen_Causeway]; A section of the Fen Causeway has been exposed and crosses the Flag Fen site [SUPPORTED: https://en.wikipedia.org/wiki/Flag_Fen]"}]'::jsonb),
    ('ccb3de8b-5c50-4204-ae6f-46cdda2e081d'::uuid, 'card_description', 'Red-painted pottery drew the first interest in Ban Chiang in 1966. At least 142 burials were dug in 1974-1975, giving up bracelets, rings, anklets, spearheads and little bells.', NULL, 'teaser-card-s033-rollback:ccb3de8b-5c50-4204-ae6f-46cdda2e081d:card_description', 'rollback of teaser-card-s033: card_description None restored on Ban Chiang', '14cbd3e6cbc6714a8f73638204d235d508440673ad01f57c597490dd13751efe|214f2a5947ee3a3ce57b90240df3f2f0c270edde05d7b6a3d9b09e531c80fc4e|214f2a5947ee3a3ce57b90240df3f2f0c270edde05d7b6a3d9b09e531c80fc4e', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Red-painted pottery drew the first interest in Ban Chiang in 1966. At least 142 burials were dug in 1974-1975, giving up bracelets, rings, anklets, spearheads and little bells."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the site''s ancient red-painted pottery is what first attracted interest [S3]; that first interest dates from the discovery in 1966 [S3]; at least 142 burials were excavated [S7]; those excavations took place in 1974-1975 [S7]; bracelets, rings, anklets, spearheads and little bells were recovered [S6]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Ban Chiang is a Thai archaeological site from which excavation has recovered evidence of early agriculture, locally made bronze and more than a hundred burials [SUPPORTED: https://en.wikipedia.org/wiki/Ban_Chiang]; Ban Chiang was discovered in 1966 and first drew attention for its red-painted pottery [SUPPORTED: https://en.wikipedia.org/wiki/Ban_Chiang]; At least 142 discrete burials were found in the 1974-1975 excavations [SUPPORTED: https://en.wikipedia.org/wiki/Ban_Chiang]; The excavations recovered bronze objects including bracelets, rings, anklets, spearheads and little bells [SUPPORTED: https://en.wikipedia.org/wiki/Ban_Chiang]; The 142 burials of 1974-1975 themselves yielded bracelets, rings, anklets, spearheads and little bells [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('cdecef79-7895-4765-af67-14e60868a220'::uuid, 'card_description', 'Low-relief carvings cut into the rocks 22 kilometres from Tacna show people fighting, dancing and hunting animals. Many believe the Miculla Petroglyphs are around 1500 years old.', NULL, 'teaser-card-s033-rollback:cdecef79-7895-4765-af67-14e60868a220:card_description', 'rollback of teaser-card-s033: card_description None restored on Miculla Petroglyphs', '6d1b3806640cecde0005b005396c7be74cbec57db12d38016a510bbb7fb0b710|eb89a564e7ccc575c129507455a931badcb3de3161aaf45c8ed88b4aa8c146e5|eb89a564e7ccc575c129507455a931badcb3de3161aaf45c8ed88b4aa8c146e5', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Low-relief carvings cut into the rocks 22 kilometres from Tacna show people fighting, dancing and hunting animals. Many believe the Miculla Petroglyphs are around 1500 years old."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the carvings are in low relief, cut into the rocks [S2]; the petroglyphs are located 22 kilometres from Tacna [S1]; they depict people fighting, dancing and hunting animals [S2]; many believe the petroglyphs are around 1500 years old [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-034 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Miculla Petroglyphs are a group of petroglyphs (rock carvings) on the San Francisco plain near the village of Miculla, Pachia, Peru - the central claim that this is a rock-art site. [SUPPORTED: https://fr.wikipedia.org/wiki/P%C3%A9troglyphes_de_Miculla]; The site lies at kilometre 22 of the Tacna road, i.e. the card''s ''22 kilometres from Tacna''. [SUPPORTED: https://fr.wikipedia.org/wiki/P%C3%A9troglyphes_de_Miculla]; The carvings are in low relief, cut into the rocks. [SUPPORTED: https://en.wikipedia.org/wiki/Miculla_petroglyphs]; The carvings depict people fighting, dancing and hunting animals. [SUPPORTED: https://en.wikipedia.org/wiki/Miculla_petroglyphs]; Many believe the petroglyphs are around 1500 years old. [SUPPORTED: https://en.wikipedia.org/wiki/Miculla_petroglyphs]; The age is not agreed: the card''s ''many believe'' implies the true date is unknown, and sources range from 500 AD to 1445 AD. [SUPPORTED: https://en.wikipedia.org/wiki/Miculla_petroglyphs]"}]'::jsonb),
    ('cee33cc0-9de5-493c-b43b-82678a6b1d8b'::uuid, 'card_description', 'On both banks of the Miño river sits Ourense, ancient Auria. The Moors destroyed it in 716; Alfonso III of Asturias rebuilt it about 877, and Al-Mansur''s attacks laid it to waste again.', NULL, 'teaser-card-s033-rollback:cee33cc0-9de5-493c-b43b-82678a6b1d8b:card_description', 'rollback of teaser-card-s033: card_description None restored on Ourense', 'd34b1e5ab82142c5dbb051bd82ec30bbd6733f12629b6fea02117c0d5e03ad10|5fb860eaf6396196c06c49491e116c32a888686fdb20f2db49247cab36b7f294|5fb860eaf6396196c06c49491e116c32a888686fdb20f2db49247cab36b7f294', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "On both banks of the Miño river sits Ourense, ancient Auria. The Moors destroyed it in 716; Alfonso III of Asturias rebuilt it about 877, and Al-Mansur''s attacks laid it to waste again."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the site was the ancient city of Auria [S4]; it lies on both banks of the Miño river [S4]; the Moors destroyed it in 716 [S1]; Alfonso III of Asturias rebuilt it about 877 [S2]; attacks by the Arab warlord Al-Mansur laid it to waste again [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-034 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Ourense is a city of Galicia, Spain, standing on both banks of the Mino river - the central claim about what kind of place this is and where. [SUPPORTED: https://en.wikipedia.org/wiki/Ourense]; Ourense is the ancient city called Auria. [SUPPORTED: https://en.wikipedia.org/wiki/Ourense]; The Moors destroyed Ourense in 716. [SUPPORTED: https://en.wikipedia.org/wiki/Ourense]; Alfonso III of Asturias rebuilt it about 8