    ('d70dd131-fac7-4c7e-b367-95c2ac945339'::uuid, 'card_description', 'Queens, princes and high-ranking officials were buried in the Valley of the Queens from roughly 1560 BC to 1130 BC. The ancients called it Ta-Set-Neferu, the Place of Beauty.', NULL, 'teaser-card-s033-rollback:d70dd131-fac7-4c7e-b367-95c2ac945339:card_description', 'rollback of teaser-card-s033: card_description None restored on Valley of the Queens', '60e50d80a1dcdeea3605759d017052bd4dd33dadc22b0d824337b0795173bbdf|0a75ddfe18ef6cf846e40b5f21c294405089a5271fb002aa4c25497565c0c8a1|0a75ddfe18ef6cf846e40b5f21c294405089a5271fb002aa4c25497565c0c8a1', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Queens, princes and high-ranking officials were buried in the Valley of the Queens from roughly 1560 BC to 1130 BC. The ancients called it Ta-Set-Neferu, the Place of Beauty."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "queens, princes and high-ranking officials were buried in the Valley of the Queens [S1]; they were buried there from roughly 1560 BC to 1130 BC [S1]; the valley was known anciently as Ta-Set-Neferu [S2]; Ta-Set-Neferu means \"The Place of Beauty\" [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-034 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Valley of the Queens is a burial place - the central claim that it is a necropolis, not a settlement or temple. [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Queens]; Queens were buried in the Valley of the Queens. [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Queens]; Princes and princesses were buried there. [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Queens]; The burials were not only royal: other high-ranking officials were buried there too. [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Queens]; The valley was used from roughly 1560 BC to 1130 BC. [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Queens]; The Valley of the Queens was known anciently as Ta-Set-Neferu. [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Queens]; Ta-Set-Neferu means ''The Place of Beauty''; the page notes it has a double meaning, the other being ''the Place of the Royal Children''. [SUPPORTED: https://en.wikipedia.org/wiki/Valley_of_the_Queens]"}]'::jsonb),
    ('d7a08c8b-4f1a-4067-a197-11922b0e34c6'::uuid, 'card_description', 'About 8 km south of Nashik lie the Pandavleni Caves, a Buddhist and Jain site. Most are viharas, monasteries, save Cave 18, a chaitya prayer hall from the 1st century BCE.', NULL, 'teaser-card-s033-rollback:d7a08c8b-4f1a-4067-a197-11922b0e34c6:card_description', 'rollback of teaser-card-s033: card_description None restored on Pandavleni Caves', '2a3a6b594c1ccb47a72a800295b29ed80b9333ad8817dc47c878a20884377f9a|b5cf491dc7faa1d3d64c7a2390c7e12eefa08a1d9d480fe7c4c9c440261e6ff5|b5cf491dc7faa1d3d64c7a2390c7e12eefa08a1d9d480fe7c4c9c440261e6ff5', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "About 8 km south of Nashik lie the Pandavleni Caves, a Buddhist and Jain site. Most are viharas, monasteries, save Cave 18, a chaitya prayer hall from the 1st century BCE."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the caves lie about 8 km south of Nashik [S1]; they are a Buddhist and Jain site [S1]; most of the caves are viharas, monasteries [S2]; Cave 18 is the exception and is a chaitya, a prayer hall [S2]; Cave 18 dates from the 1st century BCE [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-034 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Pandavleni Caves are a Buddhist and Jain cave site in India - the central claim about what kind of place this is. [SUPPORTED: https://en.wikipedia.org/wiki/Nasik_Caves]; The caves lie about 8 km south of Nashik. [SUPPORTED: https://en.wikipedia.org/wiki/Nasik_Caves]; Most of the caves are viharas. [SUPPORTED: https://en.wikipedia.org/wiki/Nasik_Caves]; Cave 18 is the exception and is a chaitya. [SUPPORTED: https://en.wikipedia.org/wiki/Nasik_Caves]; Cave 18 dates from the 1st century BCE. [SUPPORTED: https://en.wikipedia.org/wiki/Nasik_Caves]; A vihara is a monastery, which is what the card''s ''viharas, monasteries'' glosses. [SUPPORTED: https://en.wikipedia.org/wiki/Vihara]; A chaitya is a prayer hall, which is what the card''s ''chaitya prayer hall'' glosses. [SUPPORTED: https://en.wikipedia.org/wiki/Chaitya]"}]'::jsonb),
    ('df4987a2-4247-4be4-8d1c-89e3e6f816fe'::uuid, 'card_description', 'Beacon Ring''s summit stands at 408 metres within Wales, on a hill straddling the Powys and Shropshire boundary. A tree plantation covers the site, and its EIIR monogram makes it famous.', NULL, 'teaser-card-s033-rollback:df4987a2-4247-4be4-8d1c-89e3e6f816fe:card_description', 'rollback of teaser-card-s033: card_description None restored on Beacon Ring', 'a433ce908b6fd08c5094ae0a8090ac79693993002c655c787e93623275d9bb6e|f1dce679d1daef0cf8d6082ab43183b2e206f3d3741c3a20ab8b7133065b135e|f1dce679d1daef0cf8d6082ab43183b2e206f3d3741c3a20ab8b7133065b135e', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Beacon Ring''s summit stands at 408 metres within Wales, on a hill straddling the Powys and Shropshire boundary. A tree plantation covers the site, and its EIIR monogram makes it famous."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the summit at Beacon Ring is 408 metres high [S1]; that summit is within Wales [S1]; the summit is on a hill straddling the boundary between Powys and Shropshire [S1]; a tree plantation covers the site [S2]; the plantation carries an ''EIIR'' monogram [S2]; the site is famous for that monogram [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-034 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Beacon Ring is a hillfort - an archaeological site on a summit, the central claim about what kind of place this is. [SUPPORTED: https://en.wikipedia.org/wiki/Long_Mountain_(Powys)]; The hill is in Wales and straddles the Powys / Shropshire border, Powys being in Wales and Shropshire in England. [SUPPORTED: https://en.wikipedia.org/wiki/Long_Mountain_(Powys)]; The hill straddles a boundary - the Powys/Shropshire one. [SUPPORTED: https://en.wikipedia.org/wiki/Long_Mountain_(Powys)]; The summit at Beacon Ring is 408 metres high. [SUPPORTED: https://en.wikipedia.org/wiki/Long_Mountain_(Powys)]; Although the hill straddles the border, the summit itself is within Wales. [SUPPORTED: https://en.wikipedia.org/wiki/Long_Mountain_(Powys)]; A tree plantation covers the site. [SUPPORTED: https://en.wikipedia.org/wiki/Long_Mountain_(Powys)]; Beacon Ring is famous, and what it is famous for is the ''EIIR'' monogram. [SUPPORTED: https://en.wikipedia.org/wiki/Long_Mountain_(Powys)]"}]'::jsonb),
    ('e0191dff-1a40-4bd3-bfb4-1ea65cc1c2ca'::uuid, 'card_description', 'Along the Oude Rijn, the north border of the Roman Empire, stood Alphen aan den Rijn: Roman forts, the first bridge over the river, and a busy trade that ended in 240 AD.', NULL, 'teaser-card-s033-rollback:e0191dff-1a40-4bd3-bfb4-1ea65cc1c2ca:card_description', 'rollback of teaser-card-s033: card_description None restored on Alphen aan den Rijn', 'dde90a7e7cf1b421cd57201f935e29bd5cba658169601f9eef6a54f49a59a6c9|1453ca36f4c4e67ea1436414f8b6c1601f12bf13ed9f0e2d97e59c4fcd6cbc98|1453ca36f4c4e67ea1436414f8b6c1601f12bf13ed9f0e2d97e59c4fcd6cbc98', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Along the Oude Rijn, the north border of the Roman Empire, stood Alphen aan den Rijn: Roman forts, the first bridge over the river, and a busy trade that ended in 240 AD."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the Oude Rijn formed the north border of the Roman Empire [S2]; Alphen aan den Rijn stood along the Oude Rijn [S2, S4]; Roman fortifications were located along the Oude Rijn [S4]; the Romans built the first bridge over the Oude Rijn [S5]; Alphen was an important commercial site [S6]; that commerce ended in 240 AD [S6]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Alphen aan den Rijn is an ancient settlement site that already existed in the Roman era, on the Oude Rijn, the river''s old course. [SUPPORTED: https://en.wikipedia.org/wiki/Alphen_aan_den_Rijn]; The river was the north border (northern frontier) of the Roman Empire. [SUPPORTED: https://nl.wikipedia.org/wiki/Alphen_aan_den_Rijn_(plaats)]; Roman forts stood at Alphen aan den Rijn, among the fortifications along the Oude Rijn. [SUPPORTED: https://en.wikipedia.org/wiki/Alphen_aan_den_Rijn]; The Romans built the first bridge over the Oude Rijn. [SUPPORTED: https://en.wikipedia.org/wiki/Alphen_aan_den_Rijn]; Alphen was a busy trading centre (an important commercial site). [SUPPORTED: https://nl.wikipedia.org/wiki/Alphen_aan_den_Rijn_(plaats)]; The commercial/trade activity ended in 240 AD, when Germanic raids put an end to it. [SUPPORTED: https://en.wikipedia.org/wiki/Alphen_aan_den_Rijn]"}]'::jsonb),
    ('e364d6eb-f92a-44d7-80b2-025092a81561'::uuid, 'card_description', 'On a hillock across the Ravi from the city, Multan Fort''s walls rose 40 to 70 feet high around 46 bastions. The Mughal prince Murad Bakhsh built them in the 17th century.', NULL, 'teaser-card-s033-rollback:e364d6eb-f92a-44d7-80b2-025092a81561:card_description', 'rollback of teaser-card-s033: card_description None restored on Multan Fort', '264eeaa56a7d5ae02b89710bd0c6bc0d78d9d582d613b015d5d926a55af46851|3f02e4902e82f3ed8803bc438458a6b79db6504c14e7ab46f740cc7e1bda5df6|3f02e4902e82f3ed8803bc438458a6b79db6504c14e7ab46f740cc7e1bda5df6', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "On a hillock across the Ravi from the city, Multan Fort''s walls rose 40 to 70 feet high around 46 bastions. The Mughal prince Murad Bakhsh built them in the 17th century."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the fort stands on a hillock [S2]; the hillock is separated from the city by the Ravi River [S2]; the walls of the fort were 40 to 70 feet high [S6]; the fort had 46 bastions [S7]; the walls were built by the Mughal prince Murad Bakhsh [S4]; the walls were built in the 17th century [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Multan Fort was a historic fort in the city of Multan, Punjab, Pakistan. [SUPPORTED: https://en.wikipedia.org/wiki/Multan_Fort]; Multan Fort was built on a hillock. [SUPPORTED: https://en.wikipedia.org/wiki/Multan_Fort]; The fort was separated from the city by the Ravi River. [SUPPORTED: https://en.wikipedia.org/wiki/Multan_Fort]; The walls of the fort are 40 to 70 feet high. [SUPPORTED: https://en.wikipedia.org/wiki/Multan_Fort]; The fort had 46 bastions. [SUPPORTED: https://en.wikipedia.org/wiki/Multan_Fort]; The Mughal prince Murad Bakhsh built the walls of the fort. [SUPPORTED: https://en.wikipedia.org/wiki/Multan_Fort]; The walls were built in the 17th century. [SUPPORTED: https://en.wikipedia.org/wiki/Multan]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 92;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s033-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s033-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s033-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 92 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('48e08ccf-7661-47c1-9a0e-ff9e205530e0'::uuid, 'card_description', NULL), ('49cd7035-b70c-4991-b776-e5ae204ad8c5'::uuid, 'card_description', 'In the Orne department of Normandy, Habloville holds two Neolithic monuments: a stone table measuring 3.25 by 2.95 metres, and just to the south a listed tumulus.'), ('4a07cc38-1b55-4254-b0ad-fe875310caf7'::uuid, 'card_description', 'The Temple of Augustus, probably built between 27 BC and AD 14, measures about 8 by 17.3 m and 14 m high, its tetrastyle prostyle porch of Corinthian columns standing on a podium.'), ('4a1c0e1a-7ef6-4e1f-bbdb-6334304bcf52'::uuid, 'card_description', 'At Ras Shamra the port city of Ugarit held a royal palace of many courtyards and two acropolis temples to Baal and Dagan; its excavated texts echo Hebrew biblical poetry.'), ('4b635088-8799-4dc1-99de-b2b224a71d28'::uuid, 'card_description', 'The Town Walks of Dorchester follow the line of the Roman defences of Durnovaria, its ruined walls landscaped into tree-lined avenues between 1702 and 1743. Only one wall fragment survives.'), ('4c4c07a0-d94d-42fa-b1f2-a4f4ab3b8094'::uuid, 'card_description', 'Ražanj stands on the ancient Via Militaris, the Roman military highway. The settlement on it was known as Cametas in Roman times, and finds from building work confirm prehistoric habitation.'), ('4c6f2c0a-abdb-4a1d-a12c-a71403776fe4'::uuid, 'card_description', 'Koufonisi is an uninhabited islet in the Libyan Sea, 5.6 km south of cape Goudero on Crete''s eastern coast. Through the summer, tour boats cross from the port of Makry Gialos.'), ('4cab063f-a1a1-4e24-a46a-d609f2f87f53'::uuid, 'card_description', NULL), ('4cdbbcf7-6cdf-4295-be70-8f77b1e92bf4'::uuid, 'card_description', 'Hardknott Roman Fort, the remains of Mediobogdum, stands on the western side of the challenging Hardknott Pass. Leather objects from its Roman occupation have been found here.'), ('4f366f34-983c-42e1-a89d-7e8f5f77cdce'::uuid, 'card_description', 'At 2,430 meters, about 104 caves and rock shelters around Machu Picchu held the remains of about 174 individuals, interpreted largely as yanaconas rather than the Inca elite.'), ('4f89dada-27a0-4c49-bc79-5fc5ef812766'::uuid, 'card_description', 'Craterus'' ex voto at Delphi was a bronze lion hunt with Alexander the Great. French excavations uncovered walls standing 4m high between the Temple of Apollo and the theatre.'), ('5137c62f-7a51-4144-9ee1-9bd565b10bc8'::uuid, 'card_description', 'Rivas District, a Chiriqui Period site of AD 750-1500, gave up residential areas of river cobbles laid in circles 10 to 30 metres across. Paths, plazas and stairways were recorded here.'), ('5144ec8c-3071-4484-83d5-aded69094bb0'::uuid, 'card_description', 'In Luhansk Oblast, Ukraine, the Merheleva Ridge is an Eneolithic temple and burial complex of four large stone kurgans, officially announced on September 7, 2006.'), ('52827c54-91cb-4902-99fb-7b0860a71e36'::uuid, 'card_description', NULL), ('54a9488b-698d-4c49-94a4-c50dd43847fe'::uuid, 'card_description', 'Colha, one of the earliest Maya settlements, was occupied from 3400-1900 BC in the Early Preceramic period through the Middle Postclassic. Its trade may have reached the Greater Antilles.'), ('54bbb6a0-65d3-42c2-a995-0469957a1313'::uuid, 'card_description', 'Zyndram''s Hill, a prehistoric fortified settlement in the Beskid Wyspowy range, was occupied in the Early Bronze Age, 1750-1550 BC, and in the La Tene period, 200-50 BC.'), ('54dc63d1-d88f-4d40-976b-460b203a07ef'::uuid, 'card_description', NULL), ('5741eec1-d6ca-4a63-b0cb-f9a106a4acca'::uuid, 'card_description', 'Tumba Madžari, a Neolithic settlement in the Skopje valley, was uncovered in 1961/62 during trial excavations for a motorway. The Museum of Macedonia first excavated it in 1978.'), ('57ded976-9874-4832-8716-2b54c1fee102'::uuid, 'card_description', 'Table des Marchand is a dolmen on the megalithic site of Locmariaquer in Morbihan, Brittany, standing with the grand broken menhir of Er Grah and the tumulus of Er Grah.'), ('582777a5-6a82-4883-8092-ef8c9b4dc78d'::uuid, 'card_description', 'South of Wells-next-the-Sea in Norfolk, Warham Camp is an Iron Age circular hillfort 212 metres in diameter, a scheduled monument dated to between 800BC and 43AD.'), ('58486903-37c4-4aa4-866f-f7f8d66205ac'::uuid, 'card_description', 'On the Pumamarka River in Peru''s Cusco Region, Pumamarka is an archaeological park whose Aymara and Quechua name means puma village, and a National Cultural Heritage of Peru.'), ('58733868-7f7f-42e3-9d30-2fb9feb7fd05'::uuid, 'card_description', 'Hierocles lists Biannus among the 22 cities of Crete, and its Hellenistic coins survive. On a hill northwest of modern Viannos, remains run from the Orientalizing period to Roman times.'), ('58a5a5b2-735a-4fda-bf2d-52e723fd86bc'::uuid, 'card_description', NULL), ('58ad6c3e-49ea-4a21-ab5b-2735d30298d1'::uuid, 'card_description', 'In the parish of Selwood, Somerset, Roddenbury Hillfort is a univallate Iron Age hillfort covering 0.84 hectares, a Scheduled Monument that stood on the Heritage at Risk Register in 2011.'), ('5908e9f0-9f7f-43ee-8fd8-7ac446fd46c7'::uuid, 'card_description', 'On Sicily''s southeast coast, Helorus was a Greek colony of Syracuse founded in the late 8th century BC. Among them the Colonna Pizzuta, a 10.5-metre column from the 3rd century BC.'), ('5a3da9b9-6d74-4991-bfa3-3e41f600bcdf'::uuid, 'card_description', 'Near the village of Tregele in northern Anglesey stands the Llanfechell Cromlech, where Late Neolithic and Early Bronze Age rock art was found on one of its stones in 2004-2005.'), ('5ac30362-6c6f-412b-857b-3ec51df81f66'::uuid, 'card_description', NULL), ('5b9393ea-f867-4553-b497-7079cebbff61'::uuid, 'card_description', 'Chacchoben, a Maya ruin approximately 177 km south of Tulum in Quintana Roo, Mexico, means Place of Red Maize in Maya. INAH began restoration in 1994; in 2002 the site opened to the public.'), ('5c40d704-05a0-4951-a5cf-20066d444d81'::uuid, 'card_description', 'Walton Common, a 25.5 hectare Site of Special Scientific Interest, holds two saucer-shaped Bronze Age round barrows and a late Iron Age banjo enclosure that may be a univallate hillfort.'), ('5c46562f-ee30-4894-a9ce-b069e22aa698'::uuid, 'card_description', 'Alverdiscott, a village and civil parish in Torridge, Devon, England, 9 km south-south-west of Barnstaple, holds a Scheduled Ancient Monument: a Roman marching camp.'), ('5d8a7c0e-3d54-497b-a9dc-5c9cbee82670'::uuid, 'card_description', 'South of the river Vuka and northwest of Vinkovci in eastern Croatia, Markušica gave up a Scordisci site of the Late La Tene culture, dug in rescue work of the 1970s and 1980s.'), ('5db5e2c0-081a-4c69-a8c6-6105ac870e5f'::uuid, 'card_description', 'Excavations beneath the floor of the Church of the Holy Apostles Peter and Paul at Ras uncovered black-figure pottery from the 7th-6th centuries BC and a 5th-century BC princely grave.'), ('5ea99baa-5ab5-4f9f-adb9-48bc53e97363'::uuid, 'card_description', 'On the southeastern edge of the Abusir necropolis, the Lepsius No.25 Pyramid is a 5th Dynasty double tomb: the eastern tomb measures 27.7 by 21.5 m, and lacked a mortuary temple.'), ('5f0df994-58d2-4bd5-91be-252d6ae06f76'::uuid, 'card_description', 'Outside the walls of Pompeii, the Villa of Diomedes stands on two levels around 3500 square meters, facing what would have been the ancient coast line, though it is not clear it was his.'), ('60ef45e0-fd0e-414c-a000-22ddccdd332b'::uuid, 'card_description', 'Roman occupation at Keal Cotes runs from the 1st to 4th century AD. A 1960s field walk uncovered tessellated mosaic floor tiles; ploughing has left only cropmarks, visible from the air.'), ('62f21f04-c668-474e-8548-69bbdbc35620'::uuid, 'card_description', 'The Megarian Treasury at Olympia held the votive offerings of Megara: built mainly from limestone, with a roof of terracotta tiles, statues, limestone reliefs and carvings in cedarwood.'), ('631de534-1de5-4dbc-ac03-ac5ee63eb84f'::uuid, 'card_description', 'Stobno was settled in prehistoric times: Bronze Age and Early Middle Age sites lie nearby, and the village is first written in 1259, in Piast-ruled Poland since the late 10th century.'), ('63b855c8-c281-42d8-87ea-58aeeec070ef'::uuid, 'card_description', 'Mawk''allaqta, an archaeological settlement in southeastern Peru''s Puno Region, was declared a National Cultural Heritage by the country''s National Institute of Culture.'), ('648faca1-d0ae-4830-83f6-54efdf0231fe'::uuid, 'card_description', 'Marpa''s ruins straddle both sides of the river in the Cotahuasi Canyon, around 3,400 metres deep. The Inca road may follow an older route built by the Wari culture, circa 500-900 AD.'), ('64c9b400-5cab-45f2-8662-03c24c4367ce'::uuid, 'card_description', 'The Pyramid of Amenemhat I at el-Lisht, built by the founder of the Twelfth Dynasty who moved the capital from Thebes to Itj-tawy, now stands at approximately 20 m.'), ('65936955-be6f-43cc-a306-fc879106f442'::uuid, 'card_description', 'The Tours Amphitheatre stands behind the cathedral in Tours, France, a Roman amphitheatre of the 1st century AD. In front of the Roman amphitheatre, the cathedral stands.'), ('67215100-355e-4586-ae41-00838c8e1566'::uuid, 'card_description', NULL), ('673332a5-3a27-4045-a929-ddbf7ff7e824'::uuid, 'card_description', NULL), ('6880170a-df11-4dbf-8c6c-02aa4e39ec7b'::uuid, 'card_description', 'Clunia, an ancient Roman city in present-day Feldkirch, Vorarlberg, Austria, is marked on the Tabula Peutingeriana as a settlement along the Roman road network. The map still names it.'), ('68859b06-2135-4711-a160-da003d18ccca'::uuid, 'card_description', NULL), ('68c4944b-9e3a-4561-955c-33fa9978fc86'::uuid, 'card_description', 'In 1940 a cranium nearly 15,000 years old came to light at the Keilor Archaeological Site. Hearths about 31,000 years BP; megafauna remains suggest a possible Aboriginal hunting link.'), ('696fa141-d76e-4882-ab59-75f8a0d46d47'::uuid, 'card_description', 'Built in the Ionic order, the colonnade of the Garni Temple fell in the earthquake of June 4, 1679 and was rebuilt from its own stones, without mortar, in grey to bluish basalt.'), ('6a199307-b761-4214-82da-2dbd4c89832c'::uuid, 'card_description', 'On an isolated 80-metre hilltop, Cannington Camp is a univallate hillfort occupied from the Mesolithic through Roman periods. It is proposed as the site of the 878 AD Battle of Cynuit.'), ('6a43a3e7-66c7-4133-a91c-58a52cc5e0dc'::uuid, 'card_description', NULL), ('6a4cdd7d-42a8-4952-a1b9-7d6bb44f090a'::uuid, 'card_description', 'The terraces of Quriwayrachina, an archaeological site also called Quri Wayrachina, step across Peru''s Cusco Region in Anta Province, about 4 km north of the terraces of Zurite.'), ('6b0c9ab6-58dd-4989-a937-b83a957ef665'::uuid, 'card_description', NULL), ('6c736688-98d7-4c57-bf53-1f4367950131'::uuid, 'card_description', 'At Le Grand-Pressigny, carvers struck blades up to 40 cm long from caramel-coloured flint and sent them to the Alps, Brittany and Holland. The mines were active around 3000 BC.'), ('6cf9cf72-ba27-4843-bbd4-e9acfabec124'::uuid, 'card_description', 'Wanakawri is a legendary mountain and an archaeological site at 4,089 metres, one of the highest elevations near Cusco. It was one of the most important wak''as of the Inca culture.'), ('6e6a831d-bdce-400c-86af-9238e6af3e89'::uuid, 'card_description', NULL), ('6ee96ec3-9a2f-41be-ad77-f8187a54e493'::uuid, 'card_description', 'On the southeast coast of Rhodes stands Lartos, an ancient village notable for a major marble formation: lithos lartios, a distinctive gray-blue stone quarried in antiquity.'), ('70037a24-6487-4834-9b50-5242289009fe'::uuid, 'card_description', 'The Roman Bath in York was uncovered in 1929–31 while the present building rose over an earlier inn. Its Roman bathing complex is still visible inside, a rare glimpse of Roman-era York.'), ('7008f483-697f-4f0b-b2c4-5b234d28d4c7'::uuid, 'card_description', 'Lakhmir Mound rises in the Naig Valley of Sindh as a conical hill above a lower section resembling a town, where black-on-red pottery of the Indus Valley civilization lies scattered.'), ('70466849-1cf9-4af9-a442-7a4ffa6e24c9'::uuid, 'card_description', NULL), ('723fc127-d8cb-4d46-b075-ce46593b5409'::uuid, 'card_description', 'On the Argolid coast, Asine is the city the Iliad of Homer gives to Diomedes of Argos. In 1922 Swedish Crown Prince Gustaf Adolf began excavations, Sweden''s first major fieldwork in Greece.'), ('7260c83f-718a-4d70-9126-516ecd7db7a7'::uuid, 'card_description', 'At ancient Camulodunum in Colchester, Balkerne Gate is the largest surviving gateway in Roman Britain, built where the Roman road from Londinium met the town wall.'), ('72b1b9e1-8e84-402b-b1bd-a7161527bca5'::uuid, 'card_description', 'Atop Mount Pirwayuq, the site of Pirwayuq sits at approximately 3,900 meters above sea level, in the Laria District of Tayacaja Province in the Huancavelica Region.'), ('75dac040-12f2-4c78-b989-33cd3f5f07a9'::uuid, 'card_description', 'At Saqqara, stone robbers have left the Pyramid of Neferhetepes a mound of rubble with its burial chamber exposed: it once stood 16.8 m high, built for the wife of Userkaf.'), ('75f2454d-5538-42ea-87b2-ba091dec3df6'::uuid, 'card_description', 'Searching for a Roman road in 1984, the Trent and Peak Archaeological Trust uncovered two Early Neolithic longhouses at Lismore Fields, among the best-preserved in Britain.'), ('76bd4687-787b-48d8-bbb5-e0d063bbf4c6'::uuid, 'card_description', 'At Colebrooke, Devon, the agger of a Roman road still shows in a field roughly 300 metres south of Rag Lane. It fades near the village, yet a straight lane along the ridge suggests its line.'), ('77c8e01e-c8c8-4667-99f2-e36c81d6c0f8'::uuid, 'card_description', NULL), ('79132373-7a68-45e3-a174-3b1e429a12b3'::uuid, 'card_description', 'The northernmost point of Spain, Punta da Estaca de Bares reaches into the Cantabrian Sea and takes more than 2500 mm of rain a year, one of the rainiest places in Europe.'), ('7cfc73a7-180b-4378-a14a-785e9cab28a4'::uuid, 'card_description', 'About 3 km south of Manfredonia, Siponto was a port town and bishopric of Magna Graecia. In 189 BC it became the Roman colony Sipontum; in 663 AD the Slavs took and destroyed it.'), ('7e88e3ce-568c-4cea-aa71-79713b290df1'::uuid, 'card_description', 'Near the village of Berel in eastern Kazakhstan, Berel Kurgan holds numerous 5th-3rd century BCE Early Saka kurgans, vast quantities of golden jewelry, and horses buried beside their owners.'), ('81724be4-6588-41b1-8efc-364637456cdf'::uuid, 'card_description', 'Cut into the upper slopes of Whitehorse Hill in Oxfordshire, the Uffington White Horse runs 110 m in trenches of crushed white chalk, made between 1380 and 550 BC.'), ('865dcc6d-fa4c-429b-8c16-908cb96dcec2'::uuid, 'card_description', 'No one knows when Tarragona was first founded. The Scipio brothers turned it into a fortress and arsenal against the Carthaginians; Mela called it the richest town on the coast.'), ('8797faec-8590-4716-9763-310be93ef6ea'::uuid, 'card_description', 'Outside the city walls of Palmyra, in the Valley of the Tombs, stood the Tower of Elahbel. In its tombs were found fragments of very early Chinese silk yarns dated to the 1st century AD.'), ('8ef67a96-2590-4382-b575-4a15f7c468fe'::uuid, 'card_description', 'Cova Foradà, a cave in a low hill near Oliva, gave up a maxilla and fragments of a cranium. In 2010 came the most complete Neanderthal skeleton ever found on the Iberian peninsula.'), ('9116c105-f7ac-4f02-8ea4-b724c68c9464'::uuid, 'card_description', 'At Heraclea Lyncestis, the Roman emperor Hadrian built a theatre on a hill. In the Great Basilica, three naves are covered with mosaics of very rich floral and figurative iconography.'), ('94e18246-8ec7-4da8-9bad-ea33e78d2dcb'::uuid, 'card_description', 'Stobi stands near Gradsko, where the Erigon joins the Axios, on the road from the Danube to the Aegean. Its theatre was built in the 3rd century, and it kept a large number of mosaics.'), ('96395824-9c31-477a-bf51-13ecb5035d56'::uuid, 'card_description', 'Pintia was besieged and destroyed by the Romans, and with it went the Vaccean culture, religion and language. The zone has three parts: a city, a necropolis and a potter''s district.'), ('97fb3d8b-5f53-4233-a31e-80c6b2b5228a'::uuid, 'card_description', 'Daskalio, a tiny islet off Keros in the Cyclades, was once a promontory before the sea rose. Metalworking workshops dating from 2500 BCE were found there, and Naxos marble terraces it.'), ('996e0b32-f8ca-4d04-8900-ed937b729269'::uuid, 'card_description', 'Five caves on the western shore of the Mani Peninsula make up Apidima Cave. Apidima 2, with Neanderthal morphology, was dated to more than 170,000 years; Apidima 1 is older.'), ('a692e959-c6b4-45b5-96f6-65b82c883a35'::uuid, 'card_description', 'Taliata was a Roman fort on the Moesian Limes, the chain of forts along the Danube. Domitian gave its wood and earth walls stone faces in 87 AD; an early Christian basilica was found there.'), ('a945d5ef-bbbf-42bd-be5b-27c25eda9df1'::uuid, 'card_description', 'At Aguadulce in Almería, the site of La Ribera de Algaida covers 20 to 30 hectares and was occupied from the Argaric culture until the Roman Era. It was discovered in 1859.'), ('b7cc5073-ffca-4cd3-a168-3062908d4959'::uuid, 'card_description', 'On top of a South Downs hill, the Beacon Hill fort is a single rampart and a flat-bottomed ditch, now a low bank up to 6 metres wide. The area also holds an Anglo-Saxon burial mound.'), ('b8f4c5f4-c567-4605-9f3d-9475d2db6362'::uuid, 'card_description', 'In Dulan Village, the Dulan Site holds a rectangular stony coffin, dug during Japanese rule, and a giant stone pile found by Academia Sinica. Its objects date back to 3,000 years ago.'), ('c17927cb-4b63-4fa0-9c64-b72a65decaaa'::uuid, 'card_description', 'On Rhodes in the Dodecanese, the acropolis of Lindos was dominated by the massive temple of Athena Lindia, which attained its final form around 300 BC, and was excavated down to bedrock.'), ('c8529ed4-208b-45d2-9e75-58a5c3022c82'::uuid, 'card_description', 'The ruins of Pushkalavati are two sites, Bala Hisar to the south and Shaikhan Dheri to the north. According to Arrian, the city surrendered in 327/326 BCE to Alexander the Great.'), ('c8e0a91d-298d-40f1-aef8-f8503e44b05a'::uuid, 'card_description', 'Across the fens, the Fen Causeway runs 24 miles from Denver to Peterborough, thought raised on gravel up to 60 feet wide. Near its western end lies the Bronze Age route across Flag Fen.'), ('ccb3de8b-5c50-4204-ae6f-46cdda2e081d'::uuid, 'card_description', 'Red-painted pottery drew the first interest in Ban Chiang in 1966. At least 142 burials were dug in 1974-1975, giving up bracelets, rings, anklets, spearheads and little bells.'), ('cdecef79-7895-4765-af67-14e60868a220'::uuid, 'card_description', 'Low-relief carvings cut into the rocks 22 kilometres from Tacna show people fighting, dancing and hunting animals. Many believe the Miculla Petroglyphs are around 1500 years old.'), ('cee33cc0-9de5-493c-b43b-82678a6b1d8b'::uuid, 'card_description', 'On both banks of the Miño river sits Ourense, ancient Auria. The Moors destroyed it in 716; Alfonso III of Asturias rebuilt it about 877, and Al-Mansur''s attacks laid it to waste again.'), ('d70dd131-fac7-4c7e-b367-95c2ac945339'::uuid, 'card_description', 'Queens, princes and high-ranking officials were buried in the Valley of the Queens from roughly 1560 BC to 1130 BC. The ancients called it Ta-Set-Neferu, the Place of Beauty.'), ('d7a08c8b-4f1a-4067-a197-11922b0e34c6'::uuid, 'card_description', 'About 8 km south of Nashik lie the Pandavleni Caves, a Buddhist and Jain site. Most are viharas, monasteries, save Cave 18, a chaitya prayer hall from the 1st century BCE.'), ('df4987a2-4247-4be4-8d1c-89e3e6f816fe'::uuid, 'card_description', 'Beacon Ring''s summit stands at 408 metres within Wales, on a hill straddling the Powys and Shropshire boundary. A tree plantation covers the site, and its EIIR monogram makes it famous.'), ('e0191dff-1a40-4bd3-bfb4-1ea65cc1c2ca'::uuid, 'card_description', 'Along the Oude Rijn, the north border of the Roman Empire, stood Alphen aan den Rijn: Roman forts, the first bridge over the river, and a busy trade that ended in 240 AD.'), ('e364d6eb-f92a-44d7-80b2-025092a81561'::uuid, 'card_description', 'On a hillock across the Ravi from the city, Multan Fort''s walls rose 40 to 70 feet high around 46 bastions. The Mughal prince Murad Bakhsh built them in the 17th century.'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s033-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM p.written::character varying
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
